    Expr base = cast<num_t>((i * j % 7) + 1);

    // Condition for setting to 999
    Expr sum  = i + j;
    Expr cond = ((sum % 13) == 0) ||
                ((sum % 7)  == 0) ||
                ((sum % 11) == 0);

    init_path(j, i) = select(cond,
                             cast<num_t>(999),
                             base);

    // Simple but reasonably efficient schedule for initialization:
    //  - j is the contiguous dimension (x), so vectorize across j
    //  - parallelize over i (rows)
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 1;
    }

    init_path
        .vectorize(j, vec_width)
        .parallel(i);

    // Realize into the provided buffer. Buffer layout is (x=j, y=i).
    init_path.realize(path);
}

