    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // path[i][j] -> path(j, i)
            std::cerr << path(j, i) << '\n';
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to: DATA_TYPE path[N][N]
    // We use two buffers for double-buffered Floyd–Warshall.
    //
    // Mapping: C path[i][j] is stored as Buffer(j, i).
    Buffer<num_t, 2> path0(n, n);
    Buffer<num_t, 2> path1(n, n);

    // Initialize data into path0
    init_array(n, path0);

    // Halide parameters and pipeline for a single Floyd–Warshall step.
    //
    // We follow the recommended DP translation pattern:
    //   For each k:
    //     step(i,j) = min(path(i,j), path(i,k) + path(k,j))
    //   implemented as a Func that reads from an ImageParam (current path)
    //   and a scalar Param k, and then executed from a host-side loop
    //   with double-buffering.
    ImageParam path_param(type_of<num_t>(), 2, "path_param");
    Param<int> k_param("k");

    Var i("i"), j("j");

    // We cache the k-th row and column of the current matrix in 1D Funcs
    // to greatly reduce memory traffic:
    //
    //   row_k(j) = path[k][j]
    //   col_k(i) = path[i][k]
    //
    // With these, a single FW step becomes:
    //   via_k = col_k(i) + row_k(j)
    //   next[i][j] = min(path[i][j], via_k)
    //
    // This changes the number of loads of path[k][j] and path[i][k]
    // from O(N^2) per k to O(N) per k, while keeping semantics identical.
    Func row_k("row_k"), col_k("col_k");
    Func floyd_step("floyd_step");

    // Mapping between C indices and Halide coordinates:
    //
    //   C: path[i][j] -> path_param(j, i)
    //   C: path[i][k] -> path_param(k_param, i)
    //   C: path[k][j] -> path_param(j, k_param)
    //
    // row_k and col_k are 1D views of the k-th row/column.
    row_k(j) = path_param(j, k_param);       // path[k][j]
    col_k(i) = path_param(k_param, i);       // path[i][k]

    Expr direct = path_param(j, i);          // path[i][j]
    Expr via_k  = col_k(i) + row_k(j);       // path[i][k] + path[k][j]

    floyd_step(j, i) = Halide::min(direct, via_k);

    // -------------------------------------------------------------------
    // Scheduling: optimize data locality, SIMD usage, and parallelism.
    // -------------------------------------------------------------------
    Target target = get_host_target();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width <= 0) {
        vec_width = 1;
    }

    // Reasonable tile sizes for a modern multi-core CPU; tune empirically.
    const int tile_j = 32 * vec_width;  // tile width along contiguous dim (j)
    const int tile_i = 32;              // tile height along i (rows)

    // Schedule for the cached row/column:
    //  - They are computed once per FW iteration (per k) at the root.
    //  - They are O(N) each, so vectorizing across their single dimension
    //    and optionally parallelizing is cheap compared to the main step.
    row_k
        .compute_root()
        .vectorize(j, vec_width)
        .parallel(j);

    col_k
        .compute_root()
        .vectorize(i, vec_width)
        .parallel(i);

    // Schedule for the main FW step:
    //
    //  - We tile (j, i) into tile_j x tile_i blocks to improve cache
    //    locality for reading and writing the 2D matrix.
    //  - j is the fast-varying (contiguous) dimension, so we vectorize it.
    //  - We parallelize across tiles in i (io), which provides coarse-grain
    //    parallelism over independent rows/row-blocks.
    Var jo("jo"), ji("ji"), io("io"), ii("ii");

    floyd_step
        .tile(j, i, jo, io, ji, ii,
              tile_j, tile_i, TailStrategy::GuardWithIf)
        .vectorize(ji, vec_width)
        .parallel(io);

    // Bind initial data (will be updated inside the k-loop as well).
    path_param.set(path0);
    k_param.set(0); // will be updated inside the loop

    // Compile the pipeline once for the host target.
    floyd_step.compile_jit(target);

    // Double-buffering pointers
    Buffer<num_t, 2> *current_path = &path0;
    Buffer<num_t, 2> *next_path    = &path1;

    // Time only the Floyd–Warshall kernel (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 0; k < n; k++) {
        // Bind the current path and the iteration index k
        path_param.set(*current_path);
        k_param.set(k);

        // Compute the next path:
        //
        // floyd_step(j, i) = min( path_cur[i][j],
        //                         path_cur[i][k] + path_cur[k][j] )
        //
        // implemented using row_k(j) and col_k(i) internally for better
        // locality and fewer redundant loads.
        floyd_step.realize(*next_path);

        // Swap buffers for the next iteration
        std::swap(current_path, next_path);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // The final result is in *current_path
    Buffer<num_t, 2> &path = *current_path;

    // Optional printing to prevent dead-code elimination and for debugging.
    // This mirrors the style from example/gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        print_array(n, path);
    }

    // Print kernel execution time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
