                             cast<num_t>(999),
                             base);

    // ------------------------
    // Schedule for init_path:
    // ------------------------
    //
    // - j is the fast-varying (x) dimension in the Buffer, so we
    //   reorder to make j innermost.
    // - Vectorize over j to get SIMD initialization.
    // - Parallelize over i (rows) for multi-core initialization.
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

