static void print_array(int n, Buffer<num_t, 2> path) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // path[i][j] -> path(j, i)
            std::cerr << path(j, i) << '\n';
        }
    }
