    //
    // We follow the recommended DP translation pattern:
    //   For each k:
    //     step(i,j) = min(path(i,j), path(i,k) + path(k,j))
    // implemented as a Func that reads from an ImageParam (current path)
    // and a scalar Param k, and then executed from a host-side loop
    // with double-buffering.
    ImageParam path_param(type_of<num_t>(), 2, "path_param");
    Param<int> k_param("k");

    Var i("i"), j("j");
    Func floyd_step("floyd_step");

    // Mapping between C and Halide coordinates:
    //   C: path[i][j] -> path_param(j, i)
    //   C: path[i][k] -> path_param(k, i)
    //   C: path[k][j] -> path_param(j, k)
    //
    // For a fixed k (k_param), and each (i, j) we compute:
    //   current = path[i][j]
    //   via_k   = path[i][k] + path[k][j]
    //   result  = min(current, via_k)
    //
    // We explicitly hoist path[i][k] into a scalar Expr 'a_ik' so that
    // Halide/LLVM can keep it in a register across the inner j-loop.
    Expr current = path_param(j, i);
    Expr a_ik    = path_param(k_param, i);        // path[i][k], independent of j
    Expr via_k   = a_ik + path_param(j, k_param); // path[i][k] + path[k][j]

    floyd_step(j, i) = Halide::min(current, via_k);

    // -----------------------------
    // Schedule for floyd_step:
    // -----------------------------
    //
    // For each k (managed on the host), we realize floyd_step over the
    // entire N×N matrix:
    //
    //   for i in [0, N):
    //     for j in [0, N):
    //       ...
    //
    // All reads come from path_param (current_path), all writes go into
    // next_path, so for fixed k all (i,j) updates are independent.
    // That allows:
    //   - tiling in (j,i) for cache locality,
    //   - parallelization across tiles,
    //   - vectorization across j (unit-stride dimension).
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

