    const int tile_j = 64;  // tile width in columns (j, fast dimension)
    const int tile_i = 32;  // tile height in rows (i, slow dimension)

    Var jo("jo"), ji("ji");  // outer and inner j
    Var io("io"), ii("ii");  // outer and inner i

    floyd_step
        // Optional explicit bounds hint (matches buffer extent).
        .bound(j, 0, n)
        .bound(i, 0, n)
        // Tile the (j, i) space into tile_j × tile_i blocks.
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        // Within each tile, iterate j fastest for unit-stride SIMD.
        .reorder(ji, ii, jo, io)
        // Vectorize along ji (inner j within a tile).
        .vectorize(ji, vec_width)
        // Parallelize across row-tiles (io) – coarse-grained tasks.
        .parallel(io);

    // Bind initial data and compile the step once.
    path_param.set(path0);
    k_param.set(0); // will be updated inside the loop
    floyd_step.compile_jit(target);

    // Double-buffering pointers
    Buffer<num_t, 2> *current_path = &path0;
    Buffer<num_t, 2> *next_path    = &path1;

    // Time only the Floyd–Warshall kernel (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    // Outer DP loop over k is kept on the host and strictly sequential
    // (Floyd–Warshall requires that k advance in order).
    for (int k = 0; k < n; k++) {
        // Bind the current path and the iteration index k
        path_param.set(*current_path);
        k_param.set(k);

        // Compute the next path matrix for this k.
        //
        // Thanks to the schedule above, this realization:
        //   - tiles (j,i) into cache-friendly blocks,
        //   - executes tiles in parallel across CPU cores,
        //   - vectorizes across j inside each tile.
        floyd_step.realize(*next_path);

        // Swap buffers for the next iteration (O(1) pointer swap, no copy).
        std::swap(current_path, next_path);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // The final result is in *current_path
    Buffer<num_t, 2> &path = *current_path;

