    Expr sum = i + j;
    Expr cond = ((sum % 13) == 0) ||
                ((sum % 7)  == 0) ||
                ((sum % 11) == 0);

    init_path(j, i) = select(cond,
                             cast<num_t>(999),
                             base);

    // Simple, cache-friendly schedule for initialization:
    //  - j is the innermost, contiguous dimension
    //  - parallelize over rows i
    //  - vectorize across columns j
    const int init_vec = 8;  // reasonable default for modern x64
    init_path
        .compute_root()
        .parallel(i)
        .vectorize(j, init_vec);

    // Realize into the provided buffer. Buffer layout is (x=j, y=i).
    init_path.realize(path);
