static void print_array(int n, Buffer<num_t, 2> path) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            // path[i][j] -> path(j, i)
            std::cerr << path(j, i) << '\n';
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to: DATA_TYPE path[N][N]
    // We use two buffers for double-buffered Floyd–Warshall.
    //
    // Layout: path[i][j] (row-major in C) is stored as Buffer(j, i),
    // i.e. x = j (fast-varying, contiguous), y = i (row index).
    Buffer<num_t, 2> path0(n, n);
    Buffer<num_t, 2> path1(n, n);

    // Initialize data into path0
    init_array(n, path0);

    // Halide parameters and pipeline for a single Floyd–Warshall step.
    //
    // We follow the recommended DP translation pattern:
    //   For each k:
    //     step(i,j) = min(path(i,j), path(i,k) + path(k,j))
    // implemented as a Func that reads from an ImageParam (current path)
    // and a scalar Param k, and then executed from a host-side loop
    // with double-buffering.

    // Current path matrix for this k-iteration
    ImageParam path_param(type_of<num_t>(), 2, "path_param");
    // Floyd–Warshall iteration index k (scalar, bound at runtime)
    Param<int> k_param("k");

    Var i("i"), j("j");

    // Optional 1D caches for the k-th row and column:
    //   row_k(j) = path(k, j)
    //   col_k(i) = path(i, k)
    //
    // These are recomputed once per k, amortizing address computation
    // and allowing the inner update to read from small 1D buffers that
    // fit comfortably in cache.
    Func row_k("row_k"), col_k("col_k");

    // Mapping:
    //   C: path[i][j] -> path_param(j, i)
    //   C: path[i][k] -> path_param(k_param, i)
    //   C: path[k][j] -> path_param(j, k_param)
    row_k(j) = path_param(j, k_param);      // row_k[j] = path[k][j]
    col_k(i) = path_param(k_param, i);      // col_k[i] = path[i][k]

    // Main Floyd–Warshall relaxation step for a fixed k:
    //   path_next[i][j] = min(path_cur[i][j],
    //                         path_cur[i][k] + path_cur[k][j])
    //
    // In terms of our mapping:
    //   path_cur[i][j] -> path_param(j, i)
    //   path_cur[i][k] -> col_k(i)
    //   path_cur[k][j] -> row_k(j)
    Func floyd_step("floyd_step");

    Expr direct = path_param(j, i);
    Expr via_k  = col_k(i) + row_k(j);
    floyd_step(j, i) = Halide::min(direct, via_k);

    // ------------------------------------------------------------
    // Scheduling for floyd_step pipeline
    // ------------------------------------------------------------

    // Reasonably sized tiles for a 32-core x64 with large caches.
    // These can be tuned, but 64x32 is a good starting point for
    // large dense matrices.
    const int tile_j = 64;  // tile size along j (contiguous dimension)
    const int tile_i = 32;  // tile size along i (rows)
    const int vec_w  = 8;   // SIMD width across j (tune per DATA_TYPE/ISA)

    Var jo("jo"), io("io"), jj("jj"), ii("ii");

    // Compute the k-th row and column once per k-iteration.
    // Both are small O(n) buffers, so we:
    //  - vectorize along their single dimension, and
    //  - leave them sequential (their cost is negligible vs. O(n^2)).
    row_k
        .compute_root()
        .vectorize(j, vec_w);

    col_k
        .compute_root()
        .vectorize(i, vec_w);

    // For the main 2D update:
    //  - tile the (j, i) space into tile_j x tile_i blocks,
    //  - parallelize across row tiles (io),
    //  - vectorize across the innermost j tile coordinate (jj).
    //
    // Loop structure (conceptual) for each call to floyd_step.realize():
    //   for io in [0, ceil(n / tile_i)) parallel:
    //     for jo in [0, ceil(n / tile_j)):
    //       for ii in [0, tile_i):
    //         for jj in [0, tile_j) vectorized:
    //           i = io * tile_i + ii
    //           j = jo * tile_j + jj
    //           ... perform relaxation ...
    floyd_step
        .tile(j, i,  // tile in j (x) and i (y)
              jo, io,
              jj, ii,
              tile_j, tile_i)
        .parallel(io)         // distribute row-tiles across threads
        .vectorize(jj, vec_w);

    // Bind initial data and compile the step once.
    path_param.set(path0);
    k_param.set(0); // will be updated inside the loop
    floyd_step.compile_jit();

    // Double-buffering pointers
    Buffer<num_t, 2> *current_path = &path0;
    Buffer<num_t, 2> *next_path    = &path1;

    // Time only the Floyd–Warshall kernel (not initialization).
    auto start = std::chrono::high_resolution_clock::now();

    for (int k = 0; k < n; k++) {
        // Bind the current path and the iteration index k
        path_param.set(*current_path);
        k_param.set(k);

        // Compute the next path
        floyd_step.realize(*next_path);

        // Swap buffers for the next iteration (O(1) pointer swap)
        std::swap(current_path, next_path);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // The final result is in *current_path
    Buffer<num_t, 2> &path = *current_path;

    // Optional printing to prevent dead-code elimination and for debugging.
    // This mirrors the style from example/gemm.cpp.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        print_array(n, path);
    }

    // Print kernel execution time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
